def greet(name):
    return f"hello, {name}"


def shout(text):
    return text.upper()


def main(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument("name")
    parser.add_argument("--shout", action="store_true")
    args = parser.parse_args(argv)
    greeting = greet(args.name)
    if args.shout:
        greeting = shout(greeting)
    print(greeting)

